import React, { useState, useEffect, useRef, useCallback } from 'react';
import './NotesWidget_NEW.css';

// Hidden Notepad Access Button Component
export const HiddenNotepadAccessButton = ({ onOpen }) => {
  return (
    <div className="hidden-notepad-btn" title="Open Notepad" onClick={onOpen}>
      <i className="fas fa-file-text"></i>
    </div>
  );
};

const NotesWidget = ({ onClose }) => {
  // State Management
  const [notes, setNotes] = useState([]);
  const [currentNoteId, setCurrentNoteId] = useState(null);
  const [currentNoteContent, setCurrentNoteContent] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [showSearch, setShowSearch] = useState(false);
  const [notification, setNotification] = useState({ show: false, message: '', type: '' });
  
  // Widget drag/resize state
  const [widgetPos, setWidgetPos] = useState({ x: 0, y: 0 });
  const [widgetSize, setWidgetSize] = useState({ width: 800, height: 600 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragOffset, setDragOffset] = useState({ x: 0, y: 0 });
  const [isResizing, setIsResizing] = useState(false);

  const textareaRef = useRef(null);
  const widgetRef = useRef(null);
  const resizeStartRef = useRef({ x: 0, y: 0, width: 0, height: 0 });
  const notificationTimeoutRef = useRef(null);

  // Load notes from localStorage
  useEffect(() => {
    loadNotes();
  }, []);

  // Dragging functionality
  useEffect(() => {
    if (!isDragging) return;

    const handleMouseMove = (e) => {
      setWidgetPos({
        x: e.clientX - dragOffset.x,
        y: e.clientY - dragOffset.y,
      });
    };

    const handleMouseUp = () => {
      setIsDragging(false);
    };

    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);

    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging, dragOffset]);

  // Resizing functionality
  useEffect(() => {
    if (!isResizing) return;

    const handleMouseMove = (e) => {
      const newWidth = Math.max(400, resizeStartRef.current.width + (e.clientX - resizeStartRef.current.x));
      const newHeight = Math.max(300, resizeStartRef.current.height + (e.clientY - resizeStartRef.current.y));
      setWidgetSize({ width: newWidth, height: newHeight });
    };

    const handleMouseUp = () => {
      setIsResizing(false);
    };

    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);

    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isResizing]);

  const handleDragStart = (e) => {
    if (e.target.closest('.menu-bar') || e.target.closest('.resize-handle')) return;
    setIsDragging(true);
    setDragOffset({
      x: e.clientX - widgetPos.x,
      y: e.clientY - widgetPos.y,
    });
  };

  const handleResizeStart = (e) => {
    e.preventDefault();
    setIsResizing(true);
    resizeStartRef.current = {
      x: e.clientX,
      y: e.clientY,
      width: widgetSize.width,
      height: widgetSize.height,
    };
  };

  const loadNotes = () => {
    try {
      const saved = localStorage.getItem('notepad_notes');
      if (saved) {
        const parsed = JSON.parse(saved);
        setNotes(parsed);
      }
    } catch (error) {
      console.error('Error loading notes:', error);
    }
  };

  const saveNotes = (notesArray = notes) => {
    try {
      localStorage.setItem('notepad_notes', JSON.stringify(notesArray));
      return true;
    } catch (error) {
      console.error('Error saving notes:', error);
      return false;
    }
  };

  const createNewNote = () => {
    const newNote = {
      id: Date.now().toString(),
      title: 'Untitled',
      content: '',
      dateCreated: new Date().toLocaleString(),
      dateModified: new Date().toLocaleString(),
    };
    
    const updatedNotes = [newNote, ...notes];
    setNotes(updatedNotes);
    saveNotes(updatedNotes);
    setCurrentNoteId(newNote.id);
    setCurrentNoteContent('');
    showNotification('New note created', 'success');
  };

  const saveCurrentNote = () => {
    if (!currentNoteId) return;
    
    const updated = notes.map(note =>
      note.id === currentNoteId
        ? {
            ...note,
            content: currentNoteContent,
            dateModified: new Date().toLocaleString(),
            title: currentNoteContent.split('\n')[0].substring(0, 50) || 'Untitled',
          }
        : note
    );
    
    setNotes(updated);
    saveNotes(updated);
    showNotification('Note saved', 'success');
  };

  const deleteCurrentNote = () => {
    if (!currentNoteId) return;
    
    if (window.confirm('Delete this note?')) {
      const updated = notes.filter(note => note.id !== currentNoteId);
      setNotes(updated);
      saveNotes(updated);
      setCurrentNoteId(null);
      setCurrentNoteContent('');
      showNotification('Note deleted', 'success');
    }
  };

  const selectNote = (noteId) => {
    const note = notes.find(n => n.id === noteId);
    if (note) {
      setCurrentNoteId(noteId);
      setCurrentNoteContent(note.content);
    }
  };

  const exportAsText = () => {
    if (!currentNoteId) return;
    const note = notes.find(n => n.id === currentNoteId);
    const element = document.createElement('a');
    element.setAttribute('href', 'data:text/plain;charset=utf-8,' + encodeURIComponent(note.content));
    element.setAttribute('download', `${note.title || 'note'}.txt`);
    element.style.display = 'none';
    document.body.appendChild(element);
    element.click();
    document.body.removeChild(element);
    showNotification('Note exported', 'success');
  };

  const showNotification = (message, type = 'info') => {
    if (notificationTimeoutRef.current) clearTimeout(notificationTimeoutRef.current);
    setNotification({ show: true, message, type });
    notificationTimeoutRef.current = setTimeout(() => {
      setNotification({ show: false, message: '', type: '' });
    }, 3000);
  };

  const filteredNotes = searchTerm
    ? notes.filter(note =>
        note.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        note.content.toLowerCase().includes(searchTerm.toLowerCase())
      )
    : notes;

  return (
    <div
      ref={widgetRef}
      className="notepad-widget"
      style={{
        position: 'fixed',
        left: `${widgetPos.x}px`,
        top: `${widgetPos.y}px`,
        width: `${widgetSize.width}px`,
        height: `${widgetSize.height}px`,
        display: 'flex',
        flexDirection: 'column',
      }}
      onMouseDown={handleDragStart}
    >
      {/* Title Bar */}
      <div className="title-bar">
        <div className="title-bar-content" style={{ cursor: isDragging ? 'grabbing' : 'grab' }}>
          <i className="fas fa-file-text"></i>
          <span>Notepad</span>
        </div>
        <div className="title-bar-controls">
          <button className="control-btn minimize-btn" title="Minimize">_</button>
          <button className="control-btn maximize-btn" title="Maximize">□</button>
          <button className="control-btn close-btn" onClick={onClose} title="Close">✕</button>
        </div>
      </div>

      {/* Menu Bar */}
      <div className="menu-bar">
        <div className="menu-item">File</div>
        <div className="menu-item">Edit</div>
        <div className="menu-item">Format</div>
        <div className="menu-item">View</div>
        <div className="menu-item">Help</div>
      </div>

      {/* Toolbar */}
      <div className="toolbar">
        <button className="toolbar-btn" onClick={createNewNote} title="New Note">
          <i className="fas fa-file-circle-plus"></i>
        </button>
        <button className="toolbar-btn" onClick={saveCurrentNote} disabled={!currentNoteId} title="Save">
          <i className="fas fa-floppy-disk"></i>
        </button>
        <button className="toolbar-btn" onClick={exportAsText} disabled={!currentNoteId} title="Export">
          <i className="fas fa-download"></i>
        </button>
        <div className="toolbar-separator"></div>
        <button className="toolbar-btn" onClick={() => setShowSearch(!showSearch)} title="Search">
          <i className="fas fa-magnifying-glass"></i>
        </button>
        <button className="toolbar-btn" onClick={deleteCurrentNote} disabled={!currentNoteId} title="Delete">
          <i className="fas fa-trash"></i>
        </button>
      </div>

      {/* Main Content */}
      <div className="notepad-main">
        {/* Notes List Sidebar */}
        <div className="notes-sidebar">
          <div className="sidebar-header">
            <span>Notes ({filteredNotes.length})</span>
            <button className="sidebar-btn" onClick={createNewNote} title="New Note">
              <i className="fas fa-plus"></i>
            </button>
          </div>

          {/* Search Box */}
          {showSearch && (
            <div className="search-box">
              <input
                type="text"
                placeholder="Search notes..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                autoFocus
              />
            </div>
          )}

          {/* Notes List */}
          <div className="notes-list">
            {filteredNotes.length === 0 ? (
              <div className="empty-state">No notes yet. Create one to start!</div>
            ) : (
              filteredNotes.map(note => (
                <div
                  key={note.id}
                  className={`note-item ${currentNoteId === note.id ? 'active' : ''}`}
                  onClick={() => selectNote(note.id)}
                >
                  <div className="note-item-title">{note.title || 'Untitled'}</div>
                  <div className="note-item-date">{new Date(parseInt(note.id)).toLocaleDateString()}</div>
                </div>
              ))
            )}
          </div>
        </div>

        {/* Editor Area */}
        <div className="editor-area">
          {currentNoteId ? (
            <textarea
              ref={textareaRef}
              className="notepad-textarea"
              value={currentNoteContent}
              onChange={(e) => setCurrentNoteContent(e.target.value)}
              onBlur={saveCurrentNote}
              placeholder="Start typing..."
              spellCheck="true"
            />
          ) : (
            <div className="editor-empty">
              <i className="fas fa-pen-to-square"></i>
              <p>Select a note or create a new one to start editing</p>
            </div>
          )}
        </div>
      </div>

      {/* Status Bar */}
      <div className="status-bar">
        <span className="status-item">
          {currentNoteId ? `Ln ${currentNoteContent.split('\n').length}, Col ${currentNoteContent.split('\n')[currentNoteContent.split('\n').length - 1].length}` : 'Ready'}
        </span>
      </div>

      {/* Resize Handle */}
      <div className="resize-handle" onMouseDown={handleResizeStart}></div>

      {/* Notification */}
      {notification.show && (
        <div className={`notification ${notification.type}`}>
          {notification.message}
        </div>
      )}
    </div>
  );
};

export default NotesWidget;
